"""
    ode for the logistic equation
    :param _: place holder for time, not used
    :param x: x value
    :param k: slope of logistic equation
    :param g: upper bound of logistic equation
    :return: slope dx/dt
    """
def logistic_equation(_: Any, x: Any, k: Any, g: Any) -> object {
    dx = k * x * (g - x);
    return dx;
}
